static class Trie {
    // 换题时若字符不是 a-z，把 son 改成 Map<Character, Node>，去掉 - 'a'。
    // 支持 '.' 通配（LC 211）时，遇到 '.' 就枚举 26 个孩子分别向下走。
    static class Node {
        Node[] son = new Node[26];
        boolean end;
    }
    private final Node root = new Node();
    public void insert(String word) {
        Node cur = root;
        for (int i = 0;
        i < word.length();
        i++) {
            int c = word.charAt(i) - 'a';
            if (cur.son[c] == null) cur.son[c] = new Node();
            cur = cur.son[c];
        }
        cur.end = true;
    }
    public boolean search(String word) {
        Node n = walk(word);
        return n != null && n.end;
    }
    public boolean startsWith(String prefix) {
        return walk(prefix) != null;
    }
    private Node walk(String s) {
        Node cur = root;
        for (int i = 0;
        i < s.length();
        i++) {
            int c = s.charAt(i) - 'a';
            if (cur.son[c] == null) return null;
            cur = cur.son[c];
        }
        return cur;
    }
}

