// LC155 原题保证 pop、top、getMin 只在非空栈调用，push 可接收任意 int。主实现沿用此前提，不承诺统一的空栈异常；补充中显式抛 NoSuchElementException 的 MinStack 是另一实现。
import java.util.*;
// Java 常用集合、队列、堆与数组工具
class MinStack {
    // 每帧存 [当前值, 入栈后的最小值]，弹出后上一帧的最小值仍在。
    private final Deque<int[]> stack = new ArrayDeque<>();
    public MinStack() {
    }
    public void push(int val) {
        int currentMin = stack.isEmpty()
        ? val
        : Math.min(val, stack.peek()[1]);
        stack.push(new int[]{
            val, currentMin
        }
        );
    }
    public void pop() {
        stack.pop();
    }
    public int top() {
        return stack.peek()[0];
    }
    public int getMin() {
        // 最小值已写在栈顶帧的第二项，不用再扫描。
        return stack.peek()[1];
    }
}

import java.util.*;
class MyStack {
    // 单队列模拟栈，栈顶始终保持在队首。
    private final Queue<Integer> queue = new ArrayDeque<>();
    public void push(int x) {
        int oldSize = queue.size();
        queue.offer(x);
        // 只旋转入队前的旧元素，让 x 留在队首。
        for (int i = 0;
        i < oldSize;
        i++) {
            queue.offer(queue.poll());
        }
    }
    public int pop() {
        return queue.remove();
        // 队首即栈顶。
    }
    public int top() {
        return queue.element();
    }
    public boolean empty() {
        return queue.isEmpty();
    }
}

import java.util.ArrayDeque;
import java.util.Deque;
class MyQueue {
    private final Deque<Integer> inStack = new ArrayDeque<>();
    private final Deque<Integer> outStack = new ArrayDeque<>();
    public void push(int x) {
        // 入队只写 inStack，不碰出队栈
        inStack.push(x);
    }
    public int pop() {
        moveIfNeeded();
        return outStack.pop();
    }
    public int peek() {
        moveIfNeeded();
        return outStack.peek();
    }
    public boolean empty() {
        // 两边都空，队列里才没有元素
        return inStack.isEmpty() && outStack.isEmpty();
    }
    private void moveIfNeeded() {
        // 出队栈还有数就保持原顺序，避免重复倒
        if (outStack.isEmpty()) {
            while (!inStack.isEmpty()) {
                // 再压一次把队首翻到 outStack 栈顶
                outStack.push(inStack.pop());
            }
        }
    }
}

// LC208 原题：word、prefix 均非 null，长度为1..2000，且只含小写英文字母 a-z。26叉主接口不承诺其他字符或空词的行为；补充中的 Unicode 码点、空词或前缀枚举接口有独立合同。
import java.util.*;
// Java 常用集合、队列、堆与数组工具
class Trie {
    private static class TrieNode {
        TrieNode[] children = new TrieNode[26];
        boolean isWord;
    }
    private final TrieNode root = new TrieNode();
    public Trie() {
    }
    public void insert(String word) {
        TrieNode node = root;
        for (char c : word.toCharArray()) {
            int index = c - 'a';
            // 这条字母边还没有，就补一个节点再往下走
            if (node.children[index] == null) {
                node.children[index] = new TrieNode();
            }
            node = node.children[index];
        }
        // 路径只说明前缀在，isWord 才表示单词在这里结束
        node.isWord = true;
    }
    public boolean search(String word) {
        TrieNode node = find(word);
        // 必须走到末尾，并且该节点是单词结尾
        return node != null && node.isWord;
    }
    public boolean startsWith(String prefix) {
        return find(prefix) != null;
    }
    private TrieNode find(String text) {
        TrieNode node = root;
        for (char c : text.toCharArray()) {
            int index = c - 'a';
            if (node.children[index] == null) return null;
            node = node.children[index];
        }
        return node;
    }
}

import java.util.*;
import java.util.function.IntUnaryOperator;
public final class RandomizedIntSet {
    private final List<Integer> values=new ArrayList<>();
    private final Map<Integer,Integer> positions=new HashMap<>();
    private final IntUnaryOperator randomIndex;
    public RandomizedIntSet(IntUnaryOperator randomIndex) {
        this.randomIndex=Objects.requireNonNull(randomIndex);
    }
    public boolean insert(int value) {
        if (positions.containsKey(value)) return false;
        positions.put(value,values.size());
        values.add(value);
        return true;
    }
    public boolean remove(int value) {
        Integer at=positions.get(value);
        if (at==null) return false;
        int end=values.size()-1, last=values.get(end);
        if (at!=end) {
            values.set(at,last);
            positions.put(last,at);
        }
        values.remove(end);
        positions.remove(value);
        return true;
    }
    public int getRandom() {
        if (values.isEmpty()) throw new NoSuchElementException("empty set");
        int index=randomIndex.applyAsInt(values.size());
        if (index<0 || index>=values.size()) throw new IllegalArgumentException("generator index out of bounds");
        return values.get(index);
    }
}
